1	import { ConflictException, Injectable, NotFoundException } from '@nestjs/common';
2	import { SupabaseService } from '../supabase/supabase.service';
3	
4	@Injectable()
5	export class CategoriasService {
6	  constructor(private supabase: SupabaseService) {}
7	
8	  private async garantirNomeGlobalUnico(name: string, ignorarId?: number) {
9	    let query = this.supabase.client
10	      .from('categories')
11	      .select('id')
12	      .is('restaurant_id', null)
13	      .ilike('name', name.trim());
14	
15	    if (ignorarId) query = query.neq('id', ignorarId);
16	
17	    const { data, error } = await query;
18	    if (error) throw error;
19	    if (data && data.length > 0) {
20	      throw new ConflictException(`Já existe uma categoria chamada "${name.trim()}"`);
21	    }
22	  }
23	
24	  async listarGlobais() {
25	    const { data, error } = await this.supabase.client
26	      .from('categories')
27	      .select('id, name, icon_name, color_primary, color_secondary, created_at')
28	      .is('restaurant_id', null)
29	      .order('name');
30	
31	    if (error) throw error;
32	
33	    const catIds = (data ?? []).map((c) => c.id);
34	    let prodCount: Record<number, number> = {};
35	
36	    if (catIds.length > 0) {
37	      const { data: prods } = await this.supabase.client
38	        .from('products')
39	        .select('category_id')
40	        .in('category_id', catIds);
41	
42	      for (const p of prods ?? []) {
43	        prodCount[p.category_id] = (prodCount[p.category_id] ?? 0) + 1;
44	      }
45	    }
46	
47	    return {
48	      categorias: (data ?? []).map((c) => ({ ...c, total_produtos: prodCount[c.id] ?? 0 })),
49	      total: data?.length ?? 0,
50	    };
51	  }
52	
53	  async listarTiposEstabelecimento() {
54	    const { data, error } = await this.supabase.client
55	      .from('establishment_types')
56	      .select('id, name, icon_name')
57	      .order('name');
58	
59	    if (error) throw error;
60	    return { tipos: data ?? [] };
61	  }
62	
63	  private async garantirNomeTipoUnico(name: string, ignorarId?: number) {
64	    let query = this.supabase.client.from('establishment_types').select('id').ilike('name', name.trim());
65	    if (ignorarId) query = query.neq('id', ignorarId);
66	    const { data, error } = await query;
67	    if (error) throw error;
68	    if (data && data.length > 0) {
69	      throw new ConflictException(`Já existe um tipo de estabelecimento chamado "${name.trim()}"`);
70	    }
71	  }
72	
73	  async criarTipoEstabelecimento(body: { name: string; icon_name?: string }) {
74	    await this.garantirNomeTipoUnico(body.name);
75	
76	    const { data, error } = await this.supabase.client
77	      .from('establishment_types')
78	      .insert({ name: body.name, icon_name: body.icon_name ?? 'Store' })
79	      .select()
80	      .single();
81	
82	    if (error) throw error;
83	    return data;
84	  }
85	
86	  async atualizarTipoEstabelecimento(id: number, body: { name?: string; icon_name?: string }) {
87	    if (body.name !== undefined) await this.garantirNomeTipoUnico(body.name, id);
88	
89	    const campos: Record<string, any> = {};
90	    if (body.name !== undefined) campos.name = body.name;
91	    if (body.icon_name !== undefined) campos.icon_name = body.icon_name;
92	
93	    const { data, error } = await this.supabase.client
94	      .from('establishment_types')
95	      .update(campos)
96	      .eq('id', id)
97	      .select()
98	      .single();
