170	  async entregarPedidoProprio(
171	    pedidoId: number,
172	    restaurantId: number,
173	    entregaPagamento?: { metodo: string; dinheiro?: number; pix?: number },
174	  ) {
175	    return this.motoboyService.entregarProprio(pedidoId, restaurantId, entregaPagamento);
176	  }
177	
178	  private async catIdsDoRestaurante(restaurantId: number): Promise<number[]> {
179	    const { data } = await this.supabase.client
180	      .from('categories')
181	      .select('id')
182	      .or(`restaurant_id.eq.${restaurantId},restaurant_id.is.null`);
183	    return (data ?? []).map((c: any) => c.id);
184	  }
185	
186	  private async verificarProdutoDoRestaurante(produtoId: number, restaurantId: number) {
187	    const { data: prod } = await this.supabase.client
188	      .from('products').select('id, category_id, restaurant_id').eq('id', produtoId).maybeSingle();
189	    if (!prod) throw new NotFoundException('Produto não encontrado');
190	    if (prod.restaurant_id !== restaurantId) throw new NotFoundException('Produto não pertence a este restaurante');
191	    return prod;
192	  }
193	
194	  async meusProdutos(restaurantId: number) {
195	    const { data, error } = await this.supabase.client
196	      .from('products')
197	      .select('id, name, description, price, preco_promo, preco_custo, image_url, is_active, category_id, restaurant_id, tags, destaque, impressora_id, quantidade_estoque, quantidade_minima, created_at, categories(name)')
198	      .eq('restaurant_id', restaurantId)
199	      .order('destaque', { ascending: false })
200	      .order('name');
201	
202	    if (error) throw error;
203	    // category_name direto no produto (igual ao endpoint do garçom) pra telas com
204	    // filtro por categoria não precisarem buscar/montar o map à parte.
