async entregarPedidoProprio(
  pedidoId: number,
  restaurantId: number,
  entregaPagamento?: { metodo: string; dinheiro?: number; pix?: number },
) {
  return this.motoboyService.entregarProprio(pedidoId, restaurantId, entregaPagamento);
}

private async catIdsDoRestaurante(restaurantId: number): Promise<number[]> {
  const { data } = await this.supabase.client
    .from('categories')
    .select('id')
    .or(`restaurant_id.eq.${restaurantId},restaurant_id.is.null`);
  return (data ?? []).map((c: any) => c.id);
}

private async verificarProdutoDoRestaurante(produtoId: number, restaurantId: number) {
  const { data: prod } = await this.supabase.client
    .from('products').select('id, category_id, restaurant_id').eq('id', produtoId).maybeSingle();
  if (!prod) throw new NotFoundException('Produto não encontrado');
  if (prod.restaurant_id !== restaurantId) throw new NotFoundException('Produto não pertence a este restaurante');
  return prod;
}

async meusProdutos(restaurantId: number) {
  const { data, error } = await this.supabase.client
    .from('products')
    .select('id, name, description, price, preco_promo, preco_custo, image_url, is_active, category_id, restaurant_id, tags, destaque, impressora_id, quantidade_estoque, quantidade_minima, created_at, categories(name)')
    .eq('restaurant_id', restaurantId)
    .order('destaque', { ascending: false })
    .order('name');

  if (error) throw error;
  // category_name direto no produto (igual ao endpoint do garçom) pra telas com
  // filtro por categoria não precisarem buscar/montar o map à parte.
  const produtos = (data ?? []).map((p: any) => ({ ...p, category_name: p.categories?.name ?? 'Outros' }));
  return { produtos };
}

async criarProduto(
  restaurantId: number,
  body: {
    name: string; description?: string; price: number; image_url?: string;
    category_id: number; tags?: string[]; preco_promo?: number; destaque?: boolean;
    impressora_id?: number; quantidade_estoque?: number; preco_custo?: number; quantidade_minima?: number;
  },
) {
  await this.planos.verificarLimiteProdutos(restaurantId);

  // Valida se a categoria é do restaurante ou global (restaurant_id IS NULL)
  const { data: cat } = await this.supabase.client
    .from('categories').select('id, restaurant_id').eq('id', body.category_id).maybeSingle();
  if (!cat) throw new NotFoundException('Categoria não encontrada');
  if (cat.restaurant_id !== null && cat.restaurant_id !== restaurantId)
    throw new NotFoundException('Categoria não pertence a este restaurante');

  const { data, error } = await this.supabase.client
    .from('products')
    .insert({
      name: body.name,
      description: body.description ?? null,
      price: body.price,
      preco_promo: body.preco_promo ?? null,
      image_url: body.image_url ?? null,
      category_id: body.category_id,
      restaurant_id: restaurantId,
      tags: body.tags ?? [],
      destaque: body.destaque ?? false,
      impressora_id: body.impressora_id ?? null,
      quantidade_estoque: body.quantidade_estoque ?? 0,
      preco_custo: body.preco_custo ?? 0,
      quantidade_minima: body.quantidade_minima ?? 0,
      is_active: true,
    })
    .select()
    .single();

  if (error) throw error;
  return data;
}

// Importação em massa via JSON. Duplicado = mesmo nome (sem diferenciar
// maiúscula/minúscula) já cadastrado nesta loja, ou repetido dentro do
// próprio arquivo — nesses casos o item é ignorado, não dá erro geral.
async importarProdutos(restaurantId: number, itens: any[]) {
  if (!Array.isArray(itens) || itens.length === 0) {
    throw new BadRequestException('Envie uma lista de produtos');
  }

  const { data: existentes, error: erroExistentes } = await this.supabase.client
    .from('products').select('name').eq('restaurant_id', restaurantId);
  if (erroExistentes) throw erroExistentes;
  const nomesExistentes = new Set((existentes ?? []).map((p: any) => String(p.name).trim().toLowerCase()));

  const { data: categoriasProprias, error: erroCategoriasProprias } = await this.supabase.client
    .from('categories').select('id, name').eq('restaurant_id', restaurantId);
  if (erroCategoriasProprias) throw erroCategoriasProprias;
  const { data: categoriasGlobais, error: erroCategoriasGlobais } = await this.supabase.client
    .from('categories').select('id, name').is('restaurant_id', null);
  if (erroCategoriasGlobais) throw erroCategoriasGlobais;

  const categoriaPorNome = new Map<string, number>();
  [...(categoriasProprias ?? []), ...(categoriasGlobais ?? [])].forEach((c: any) => {
    const chave = String(c.name).trim().toLowerCase();
    if (!categoriaPorNome.has(chave)) categoriaPorNome.set(chave, c.id);
  });

  const importados: string[] = [];
  const ignorados: { name: string; motivo: string }[] = [];

  for (const item of itens ?? []) {
    const nome = String(item?.name ?? '').trim();
    if (!nome) {
      ignorados.push({ name: String(item?.name ?? '(sem nome)'), motivo: 'nome ausente' });
      continue;
    }
    const chaveNome = nome.toLowerCase();
    if (nomesExistentes.has(chaveNome)) {
      ignorados.push({ name: nome, motivo: 'já existe um produto com esse nome' });
      continue;
    }
    const preco = Number(item?.price);
    if (item?.price == null || Number.isNaN(preco)) {
      ignorados.push({ name: nome, motivo: 'preço inválido' });
      continue;
    }
    const nomeCategoria = String(item?.category ?? item?.categoria ?? '').trim();
    if (!nomeCategoria) {
      ignorados.push({ name: nome, motivo: 'categoria ausente' });
      continue;
    }

    let categoryId = categoriaPorNome.get(nomeCategoria.toLowerCase());
    if (categoryId == null) {
      const { data: novaCategoria, error: erroCategoria } = await this.supabase.client
        .from('categories').insert({ name: nomeCategoria, restaurant_id: restaurantId }).select('id').single();
      if (erroCategoria) {
        ignorados.push({ name: nome, motivo: 'não foi possível criar a categoria' });
        continue;
      }
      categoryId = novaCategoria.id;
      categoriaPorNome.set(nomeCategoria.toLowerCase(), categoryId as number);
    }

    try {
      await this.planos.verificarLimiteProdutos(restaurantId);
    } catch {
      ignorados.push({ name: nome, motivo: 'limite de produtos do plano atingido' });
      continue;
    }

    const { error } = await this.supabase.client.from('products').insert({
      name: nome,
      description: item?.description ?? null,
      price: preco,
      preco_promo: item?.preco_promo != null ? Number(item.preco_promo) : null,
      image_url: item?.image_url ?? null,
      category_id: categoryId,
      restaurant_id: restaurantId,
      tags: Array.isArray(item?.tags) ? item.tags : [],
      destaque: !!item?.destaque,
      quantidade_estoque: item?.quantidade_estoque != null ? Number(item.quantidade_estoque) : 0,
      preco_custo: item?.preco_custo != null ? Number(item.preco_custo) : 0,
      quantidade_minima: item?.quantidade_minima != null ? Number(item.quantidade_minima) : 0,
      is_active: true,
    });

    if (error) {
      ignorados.push({ name: nome, motivo: 'erro ao salvar' });
      continue;
    }

    nomesExistentes.add(chaveNome);
    importados.push(nome);
  }

  return { total: itens.length, importados: importados.length, nomes_importados: importados, ignorados };
}

async editarProduto(produtoId: number, restaurantId: number, body: any) {
  await this.verificarProdutoDoRestaurante(produtoId, restaurantId);

  const update: any = {};
  if (body.name !== undefined) update.name = body.name;
  if (body.description !== undefined) update.description = body.description ?? null;
  if (body.price !== undefined) update.price = body.price;
  if (body.preco_promo !== undefined) update.preco_promo = body.preco_promo ?? null;
  if (body.image_url !== undefined) update.image_url = body.image_url ?? null;
  if (body.tags !== undefined) update.tags = body.tags;
  if (body.destaque !== undefined) update.destaque = body.destaque;
  if (body.impressora_id !== undefined) update.impressora_id = body.impressora_id ?? null;
  if (body.quantidade_estoque !== undefined) update.quantidade_estoque = body.quantidade_estoque;
  if (body.preco_custo !== undefined) update.preco_custo = body.preco_custo;
  if (body.quantidade_minima !== undefined) update.quantidade_minima = body.quantidade_minima;
  if (body.category_id !== undefined) {
    const { data: cat } = await this.supabase.client
      .from('categories').select('id, restaurant_id').eq('id', body.category_id).maybeSingle();
    if (!cat) throw new NotFoundException('Categoria não encontrada');
    if (cat.restaurant_id !== null && cat.restaurant_id !== restaurantId)
      throw new NotFoundException('Categoria não pertence a este restaurante');
    update.category_id = body.category_id;
  }

  const { data, error } = await this.supabase.client
    .from('products').update(update).eq('id', produtoId).select().single();
  if (error) throw error;
  return data;
}

async deletarProduto(produtoId: number, restaurantId: number) {
  await this.verificarProdutoDoRestaurante(produtoId, restaurantId);
  const { error } = await this.supabase.client.from('products').delete().eq('id', produtoId);
  if (error) throw error;
  return { ok: true };
}

async toggleProduto(produtoId: number, restaurantId: number, ativo: boolean) {
  await this.verificarProdutoDoRestaurante(produtoId, restaurantId);
  return this.produtos.toggleAtivo(produtoId, ativo);
}

// ── Combos ──────────────────────────────────────────────────────────────────

// Não filtra por estoque aqui — essa listagem alimenta tanto a tela de gestão de
// combos (dono precisa ver os inativos/sem estoque pra corrigir) quanto o picker
// de venda (restaurante-salao filtra `disponivel` no client, igual já faz com produto).
async meusCombos(restaurantId: number) {
  return { combos: await this.combosService.listarComDisponibilidade(restaurantId) };
}

async getComboDetalhe(comboId: number, restaurantId: number) {
  const { data: combo } = await this.supabase.client
    .from('combos').select('*').eq('id', comboId).eq('restaurant_id', restaurantId).maybeSingle();
  if (!combo) throw new NotFoundException('Combo não encontrado');

  const { data: items } = await this.supabase.client
    .from('combo_items')
    .select('id, quantity, product_id, preco_no_combo, products(id, name, price, image_url)')
    .eq('combo_id', comboId);

  return { ...combo, items: items ?? [] };
}

// Preço (R$) e Preço promo (R$) do combo NÃO vêm do client (Zero Trust) — são
// calculados aqui a partir do preço real de cada produto (tabela `products`) e do
// `preco_no_combo` que o dono escolheu pra cada item (o que ele decide cobrar por
// aquele produto especificamente dentro do combo).
private async calcularPrecosCombo(restaurantId: number, items: { product_id: number; quantity: number; preco_no_combo: number }[]) {
  if (!items?.length) throw new BadRequestException('Adicione pelo menos 1 produto ao combo');

  const prodIds = items.map((i) => i.product_id);
  const { data: produtos } = await this.supabase.client
    .from('products').select('id, price').eq('restaurant_id', restaurantId).in('id', prodIds);
  const prodMap = Object.fromEntries((produtos ?? []).map((p) => [p.id, p]));

  let precoTotal = 0;
  let precoPromoTotal = 0;
  for (const item of items) {
    const prod = prodMap[item.product_id];
    if (!prod) throw new BadRequestException(`Produto ${item.product_id} não encontrado`);
    if (item.preco_no_combo == null || item.preco_no_combo < 0) {
      throw new BadRequestException('Informe o valor cobrado no combo pra cada produto');
    }
    precoTotal += prod.price * item.quantity;
    precoPromoTotal += item.preco_no_combo * item.quantity;
  }

  return {
    price: parseFloat(precoTotal.toFixed(2)),
    preco_promo: parseFloat(precoPromoTotal.toFixed(2)),
  };
}

async criarCombo(restaurantId: number, body: {
  name: string; description?: string;
  image_url?: string; destaque?: boolean; items: { product_id: number; quantity: number; preco_no_combo: number }[];
}) {
  const { price, preco_promo } = await this.calcularPrecosCombo(restaurantId, body.items);

  const { data: combo, error } = await this.supabase.client
    .from('combos')
    .insert({
      restaurant_id: restaurantId,
      name: body.name,
      description: body.description ?? null,
      price,
      preco_promo,
      image_url: body.image_url ?? null,
      destaque: body.destaque ?? false,
      is_active: true,
    })
    .select()
    .single();
  if (error) throw error;

  await this.supabase.client.from('combo_items').insert(
    body.items.map((i) => ({ combo_id: combo.id, product_id: i.product_id, quantity: i.quantity, preco_no_combo: i.preco_no_combo })),
  );

  return this.getComboDetalhe(combo.id, restaurantId);

