  const { data: caixa } = await this.supabase.client
    .from('caixas').select('id, nome_operador, valor_inicial, entradas, saidas').eq('restaurant_id', restaurantId).eq('status', 'aberto').maybeSingle();
  if (!caixa) throw new NotFoundException('Nenhum caixa aberto');

  // Sangria em espécie não pode passar do que tem fisicamente no caixa — sangria em
  // pix/transferência/cartão não mexe no dinheiro físico, então não trava por saldo.
  if (!body.meio || body.meio === 'dinheiro') {
    const emDinheiro = (arr: any[]) => ((arr ?? []) as any[])
      .filter((x) => !x.meio || x.meio === 'dinheiro')
      .reduce((s: number, x: any) => s + (x.valor ?? 0), 0);
    const saldoEspecie = (caixa.valor_inicial ?? 0) + emDinheiro(caixa.entradas) - emDinheiro(caixa.saidas);
    if (Number(body.valor) > saldoEspecie) {
      throw new BadRequestException(
        `Caixa não tem saldo em espécie suficiente pra essa sangria (disponível: R$ ${saldoEspecie.toFixed(2)}). Registre uma Adição antes.`,
      );
    }
  }

  const saidas = (caixa.saidas ?? []) as any[];
  const nova: any = { descricao: body.descricao.trim(), valor: Number(body.valor), criado_em: new Date().toISOString() };
  if (body.meio) nova.meio = body.meio;
  const { error } = await this.supabase.client.from('caixas').update({ saidas: [...saidas, nova] }).eq('id', caixa.id);
  if (error) throw error;

  const recibo = await this.imprimirReciboMovimento(restaurantId, 'Sangria', nova, caixa.nome_operador);
  return { ...nova, caixa_id: caixa.id, recibo };
}

// Remove uma saída específica do caixa (usado pro estorno automático de repasse de
// garçom) — casa por criado_em porque índice no array pode mudar se outras saídas
// forem removidas antes.
private async removerSaidaPorCriadoEm(restaurantId: number, caixaId: number, criadoEm: string) {
  const { data: caixa } = await this.supabase.client
    .from('caixas').select('id, saidas').eq('id', caixaId).eq('restaurant_id', restaurantId).eq('status', 'aberto').maybeSingle();
  if (!caixa) throw new BadRequestException('O caixa desse lançamento já foi fechado — não é possível estornar automaticamente.');

  const saidas = (caixa.saidas ?? []) as any[];
  const novasSaidas = saidas.filter((s) => s.criado_em !== criadoEm);
  const { error } = await this.supabase.client.from('caixas').update({ saidas: novasSaidas }).eq('id', caixa.id);
  if (error) throw error;
}

// Estorna uma saída lançada por engano (ex: sangria automática de gorjeta que não devia
// existir) — remove o registro do array e o valor volta a contar no saldo do caixa.
async estornarSaida(restaurantId: number, index: number) {
  const { data: caixa } = await this.supabase.client
    .from('caixas').select('id, saidas').eq('restaurant_id', restaurantId).eq('status', 'aberto').maybeSingle();
  if (!caixa) throw new NotFoundException('Nenhum caixa aberto');

  const saidas = (caixa.saidas ?? []) as any[];
  if (index < 0 || index >= saidas.length) throw new BadRequestException('Saída não encontrada');

  const novasSaidas = saidas.filter((_, i) => i !== index);
  const { error } = await this.supabase.client.from('caixas').update({ saidas: novasSaidas }).eq('id', caixa.id);
  if (error) throw error;
  return { ok: true };
}

async adicionarEntrada(restaurantId: number, body: { descricao: string; valor: number; meio?: string }) {
  if (!body.valor || body.valor <= 0) throw new BadRequestException('Valor da entrada deve ser maior que zero');
  if (!body.descricao?.trim()) throw new BadRequestException('Descrição da entrada é obrigatória');

  const { data: caixa } = await this.supabase.client
    .from('caixas').select('id, nome_operador, entradas').eq('restaurant_id', restaurantId).eq('status', 'aberto').maybeSingle();
  if (!caixa) throw new NotFoundException('Nenhum caixa aberto');

  const entradas = (caixa.entradas ?? []) as any[];
  const nova: any = { descricao: body.descricao.trim(), valor: Number(body.valor), criado_em: new Date().toISOString() };
  if (body.meio) nova.meio = body.meio;
  const { error } = await this.supabase.client.from('caixas').update({ entradas: [...entradas, nova] }).eq('id', caixa.id);
  if (error) throw error;

  const recibo = await this.imprimirReciboMovimento(restaurantId, 'Adição', nova, caixa.nome_operador);
  return { ...nova, recibo };
}

async relatorioFretes(restaurantId: number, periodo: 'hoje' | 'semana' | 'mes' | 'ano' | 'tudo') {
  const agora = new Date();
  let dataInicio: string | null = null;

  if (periodo === 'hoje') {
    const d = new Date(agora); d.setHours(0, 0, 0, 0);
    dataInicio = d.toISOString();
  } else if (periodo === 'semana') {
    const d = new Date(agora); d.setDate(d.getDate() - 7);
    dataInicio = d.toISOString();
  } else if (periodo === 'mes') {
    const d = new Date(agora); d.setDate(1); d.setHours(0, 0, 0, 0);
    dataInicio = d.toISOString();
  } else if (periodo === 'ano') {
    const d = new Date(agora); d.setMonth(0, 1); d.setHours(0, 0, 0, 0);
    dataInicio = d.toISOString();
  }

  let q = this.supabase.client
    .from('orders')
    .select('id, total, frete_cobrado, troco_para, payment_method, status, created_at, motoboy_id, motoboys(name)')
    .eq('restaurant_id', restaurantId)
    .eq('status', 'delivered');

