1	import { BadRequestException, ConflictException, Injectable, UnauthorizedException } from '@nestjs/common';
2	import { ConfigService } from '@nestjs/config';
3	import * as bcrypt from 'bcryptjs';
4	import * as crypto from 'crypto';
5	import * as jwt from 'jsonwebtoken';
6	import { SupabaseService } from '../supabase/supabase.service';
7	import { SupabaseJwtService } from '../auth/supabase-jwt.service';
8	
9	const SESSION_TTL_MS = 30 * 24 * 60 * 60 * 1000; // igual ao expiresIn do JWT
10	
11	// identificador/email/phone entram direto num filtro .or() do PostgREST — sem
12	// validar formato, um valor com vírgula/parênteses injeta cláusulas extras
13	// no filtro (ex. ",id.gt.0").
14	const EMAIL_RE = /^[^\s,()]+@[^\s,()]+\.[^\s,()]+$/;
15	const PHONE_RE = /^\+?[0-9]{8,15}$/;
16	
17	export interface CadastroMotoboyBody {
18	  name: string;
19	  phone: string;
20	  email: string;
21	  password: string;
22	  foto_perfil: string;
23	  documento_frente: string;
24	  documento_verso?: string;
25	  comprovante_endereco: string;
26	  // Token da sessão de cliente (Supabase Auth) já logada, se houver — usado
27	  // pra vincular a conta e promover user_profiles.role pra 'motoboy'.
28	  supabase_access_token?: string;
29	}
30	
31	const BUCKET = 'motoboy-documentos';
32	
33	@Injectable()
34	export class MotoboyAuthService {
35	  constructor(
36	    private supabase: SupabaseService,
37	    private config: ConfigService,
38	    private supabaseJwt: SupabaseJwtService,
39	  ) {}
40	
41	  // Se veio um token de cliente logado, vincula o motoboy a essa conta e
42	  // promove user_profiles.role pra 'motoboy' — a pessoa deixa de contar como
43	  // cliente comum a partir daqui (decisão do produto).
44	  private async vincularContaCliente(motoboyId: number, supabaseAccessToken?: string) {
45	    if (!supabaseAccessToken) return;
46	
47	    const verified = await this.supabaseJwt.verificar(supabaseAccessToken);
48	    const userId = verified?.sub;
49	    if (!userId) return;
50	
51	    await this.supabase.client.from('motoboys').update({ user_id: userId }).eq('id', motoboyId);
52	    await this.supabase.client
53	      .from('user_profiles')
54	      .update({ role: 'motoboy', updated_at: new Date().toISOString() })
55	      .eq('id', userId);
56	  }
57	
58	  private gerarToken(motoboyId: number, sessionId: string): string {
59	    const secret = this.config.getOrThrow('MOTOBOY_JWT_SECRET');
60	    return jwt.sign({ motoboyId, sessionId }, secret, { expiresIn: '30d' });
61	  }
62	
63	  // Só abre sessão nova se não houver outra ativa (ou se a anterior já expirou) —
64	  // update condicional atômico evita corrida entre dois logins simultâneos.
65	  private async abrirSessao(motoboyId: number): Promise<string> {
66	    const sessionId = crypto.randomUUID();
67	    const nowIso = new Date().toISOString();
68	    const expiresAt = new Date(Date.now() + SESSION_TTL_MS).toISOString();
69	
70	    const { data } = await this.supabase.client
71	      .from('motoboys')
72	      .update({ active_session_id: sessionId, session_expires_at: expiresAt })
73	      .eq('id', motoboyId)
74	      .or(`active_session_id.is.null,session_expires_at.lt.${nowIso}`)
75	      .select('id')
76	      .maybeSingle();
77	
78	    if (!data) {
79	      throw new ConflictException('Este motoboy já está logado em outro dispositivo. Peça pro estabelecimento liberar o acesso.');
80	    }
81	    return sessionId;
82	  }
83	
84	  private async criarSessaoEToken(motoboyId: number): Promise<string> {
85	    const sessionId = await this.abrirSessao(motoboyId);
86	    return this.gerarToken(motoboyId, sessionId);
87	  }
88	
89	  async logout(motoboyId: number) {
90	    await this.supabase.client
91	      .from('motoboys')
92	      .update({ active_session_id: null, session_expires_at: null })
93	      .eq('id', motoboyId);
94	    return { ok: true };
95	  }
96	
97	  // Bucket privado — grava o path do objeto, não a URL (URL é gerada sob demanda via signed URL).
98	  private async uploadDocumento(motoboyId: number, campo: string, base64: string): Promise<string> {
99	    const matches = base64.match(/^data:([\w/+-]+);base64,(.+)$/);
100	    const mimeType = matches ? matches[1] : 'image/jpeg';
101	    const raw = matches ? matches[2] : base64;
102	    const buffer = Buffer.from(raw, 'base64');
103	    const ext = mimeType === 'application/pdf' ? 'pdf' : mimeType === 'image/png' ? 'png' : 'jpg';
104	    const path = `${motoboyId}/${campo}-${Date.now()}.${ext}`;
105	
106	    const { error } = await this.supabase.client.storage
107	      .from(BUCKET)
108	      .upload(path, buffer, { contentType: mimeType, upsert: true });
109	    if (error) throw error;
110	
111	    return path;
112	  }
113	
114	  async cadastro(body: CadastroMotoboyBody) {
115	    if (!body.email && !body.phone) throw new BadRequestException('Informe telefone ou e-mail');
116	    if (!body.password || body.password.length < 8) throw new BadRequestException('Senha deve ter no mínimo 8 caracteres');
117	    if (body.email && !EMAIL_RE.test(body.email)) throw new BadRequestException('E-mail inválido');
118	    if (body.phone && !PHONE_RE.test(body.phone)) throw new BadRequestException('Telefone inválido');
119	
120	    const { data: existente } = await this.supabase.client
121	      .from('motoboys')
122	      .select('id')
123	      .or(`email.eq.${body.email},phone.eq.${body.phone}`)
124	      .maybeSingle();
125	    if (existente) throw new ConflictException('Já existe um cadastro com este telefone ou e-mail');
126	
127	    const passwordHash = await bcrypt.hash(body.password, 10);
128	
129	    const { data: motoboy, error } = await this.supabase.client
130	      .from('motoboys')
131	      .insert({
132	        name: body.name,
133	        phone: body.phone,
134	        email: body.email,
135	        password_hash: passwordHash,
136	        precisa_completar_cadastro: false,
137	      })
138	      .select('id')
139	      .single();
140	    if (error) throw error;
141	
142	    const [foto_perfil_url, documento_frente_url, documento_verso_url, comprovante_endereco_url] = await Promise.all([
143	      this.uploadDocumento(motoboy.id, 'foto-perfil', body.foto_perfil),
144	      this.uploadDocumento(motoboy.id, 'documento-frente', body.documento_frente),
145	      body.documento_verso ? this.uploadDocumento(motoboy.id, 'documento-verso', body.documento_verso) : Promise.resolve(null),
146	      this.uploadDocumento(motoboy.id, 'comprovante-endereco', body.comprovante_endereco),
147	    ]);
148	
149	    await this.supabase.client
150	      .from('motoboys')
151	      .update({ foto_perfil_url, documento_frente_url, documento_verso_url, comprovante_endereco_url })
152	      .eq('id', motoboy.id);
153	
154	    await this.vincularContaCliente(motoboy.id, body.supabase_access_token);
155	
156	    return { token: await this.criarSessaoEToken(motoboy.id) };
157	  }
158	
159	  async login(identificador: string, password: string) {
160	    if (!EMAIL_RE.test(identificador) && !PHONE_RE.test(identificador)) {
161	      throw new UnauthorizedException('Credenciais inválidas');
162	    }
163	
164	    const { data: motoboy } = await this.supabase.client
165	      .from('motoboys')
166	      .select('id, password_hash, is_active')
167	      .or(`email.eq.${identificador},phone.eq.${identificador}`)
168	      .maybeSingle();
169	
170	    if (!motoboy?.password_hash) throw new UnauthorizedException('Credenciais inválidas');
171	    if (!motoboy.is_active) throw new UnauthorizedException('Conta desativada');
172	
173	    const ok = await bcrypt.compare(password, motoboy.password_hash);
174	    if (!ok) throw new UnauthorizedException('Credenciais inválidas');
175	
176	    return { token: await this.criarSessaoEToken(motoboy.id) };
177	  }
178	
179	  // Motoboys antigos (criados antes do login por senha) — completam cadastro usando o token legado.
180	  async completarCadastro(motoboyId: number, body: CadastroMotoboyBody) {
181	    if (!body.password || body.password.length < 8) throw new BadRequestException('Senha deve ter no mínimo 8 caracteres');
182	
183	    const passwordHash = await bcrypt.hash(body.password, 10);
184	
185	    const [foto_perfil_url, documento_frente_url, documento_verso_url, comprovante_endereco_url] = await Promise.all([
186	      this.uploadDocumento(motoboyId, 'foto-perfil', body.foto_perfil),
187	      this.uploadDocumento(motoboyId, 'documento-frente', body.documento_frente),
188	      body.documento_verso ? this.uploadDocumento(motoboyId, 'documento-verso', body.documento_verso) : Promise.resolve(null),
189	      this.uploadDocumento(motoboyId, 'comprovante-endereco', body.comprovante_endereco),
190	    ]);
191	
192	    const { error } = await this.supabase.client
193	      .from('motoboys')
194	      .update({
195	        name: body.name,
196	        phone: body.phone,
197	        email: body.email,
198	        password_hash: passwordHash,
199	        foto_perfil_url,
200	        documento_frente_url,
201	        documento_verso_url,
202	        comprovante_endereco_url,
203	        precisa_completar_cadastro: false,
204	      })
205	      .eq('id', motoboyId);
206	    if (error) throw error;
207	
208	    await this.vincularContaCliente(motoboyId, body.supabase_access_token);
209	
210	    return { token: await this.criarSessaoEToken(motoboyId) };
211	  }
212	}
