559	  async editarItem(comandaId: number, restaurantId: number, itemId: number, body: { quantity?: number; observacao?: string }) {
560	    const comanda = await this.buscarComanda(comandaId, restaurantId);
561	    // Venda balcão só envia os itens pra cozinha/bar depois de paga (ver `adicionarItens`/
562	    // `pagar`) — quando o item chega na Produção a comanda já está com status 'paga', então
563	    // precisa liberar edição de observação mesmo paga (só pra venda balcão; quantidade
564	    // continua travada, já foi cobrada).
565	    const podeEditar = ['aberta', 'fechada_garcom'].includes(comanda.status)
566	      || (comanda.is_venda_balcao && comanda.status === 'paga');
567	    if (!podeEditar) {
568	      throw new BadRequestException('Comanda já foi paga ou cancelada');
569	    }
570	    if (comanda.status === 'paga' && body.quantity !== undefined) {
571	      throw new BadRequestException('Não é possível alterar quantidade de uma venda já finalizada');
572	    }
573	
574	    const { data: item } = await this.supabase.client
575	      .from('order_items').select('id, product_id, quantity').eq('id', itemId).eq('order_id', comandaId).maybeSingle();
576	    if (!item) throw new NotFoundException('Item não encontrado');
577	
578	    const update: Record<string, unknown> = {};
579	    if (body.quantity !== undefined) {
580	      if (body.quantity < 1) throw new BadRequestException('Quantidade mínima é 1');
581	      update.quantity = body.quantity;
582	    }
583	    if (body.observacao !== undefined) update.observacao = body.observacao?.trim() || null;
584	
585	    const { error } = await this.supabase.client.from('order_items').update(update).eq('id', itemId);
586	    if (error) throw error;
587	
588	    if (body.quantity !== undefined && body.quantity !== item.quantity) {
589	      await this.estoque.ajustarPorDelta(item.product_id, item.quantity, body.quantity);
590	    }
591	
592	    if (comanda.status !== 'paga') {
593	      const { data: todosItens } = await this.supabase.client.from('order_items').select('quantity, unit_price').eq('order_id', comandaId);
594	      const total = (todosItens ?? []).reduce((acc: number, i: any) => acc + i.quantity * i.unit_price, 0);
595	      await this.supabase.client.from('orders').update({ total: parseFloat(total.toFixed(2)) }).eq('id', comandaId);
596	    }
597	
598	    return this.comandaDetalhe(comandaId, restaurantId);
599	  }
