1	import { ConflictException, Injectable, NotFoundException } from '@nestjs/common';
2	import { SupabaseService } from '../supabase/supabase.service';
3	
4	@Injectable()
5	export class TagsService {
6	  constructor(private supabase: SupabaseService) {}
7	
8	  private async garantirNomeTagUnico(name: string, ignorarId?: number) {
9	    let query = this.supabase.client.from('tags_catalogo').select('id').ilike('name', name.trim());
10	    if (ignorarId) query = query.neq('id', ignorarId);
11	    const { data, error } = await query;
12	    if (error) throw error;
13	    if (data && data.length > 0) {
14	      throw new ConflictException(`Já existe uma tag chamada "${name.trim()}"`);
15	    }
16	  }
17	
18	  async listar(apenasAtivas = true) {
19	    let q = this.supabase.client.from('tags_catalogo').select('*').order('ordem').order('name');
20	    if (apenasAtivas) q = q.eq('ativo', true);
21	    const { data, error } = await q;
22	    if (error) throw error;
23	    return { tags: data ?? [] };
24	  }
25	
26	  async criar(body: { name: string; slug: string; descricao?: string; is_auto?: boolean; ordem?: number }) {
27	    await this.garantirNomeTagUnico(body.name);
28	
29	    const { data, error } = await this.supabase.client
30	      .from('tags_catalogo')
31	      .insert({
32	        name: body.name,
33	        slug: body.slug,
34	        descricao: body.descricao ?? null,
35	        is_auto: body.is_auto ?? false,
36	        ordem: body.ordem ?? 0,
37	        ativo: true,
38	      })
39	      .select()
40	      .single();
41	    if (error) throw error;
42	    return data;
43	  }
44	
45	  async atualizar(id: number, body: Partial<{ name: string; descricao: string; ordem: number; ativo: boolean }>) {
46	    if (body.name !== undefined) await this.garantirNomeTagUnico(body.name, id);
47	
48	    const campos: any = {};
49	    if (body.name !== undefined) campos.name = body.name;
50	    if (body.descricao !== undefined) campos.descricao = body.descricao;
51	    if (body.ordem !== undefined) campos.ordem = body.ordem;
52	    if (body.ativo !== undefined) campos.ativo = body.ativo;
53	
54	    const { data, error } = await this.supabase.client
55	      .from('tags_catalogo').update(campos).eq('id', id).select().single();
56	    if (error) throw error;
57	    if (!data) throw new NotFoundException('Tag não encontrada');
58	    return data;
59	  }
60	
61	  async remover(id: number) {
62	    const { error } = await this.supabase.client.from('tags_catalogo').delete().eq('id', id);
63	    if (error) throw error;
64	    return { ok: true };
65	  }
66	
67	  // Retorna produtos para cada tag ativa de um restaurante
68	  async getCarrosseis(restaurantId: number) {
69	    const { tags } = await this.listar(true);
70	    const result: { tag: any; produtos: any[] }[] = [];
71	
72	    for (const tag of tags) {
73	      let produtos: any[] = [];
74	
75	      if (tag.slug === 'mais_vendidos') {
76	        // Auto: top produtos por volume de vendas
77	        const { data: itens } = await this.supabase.client
78	          .from('order_items')
79	          .select('product_id, quantity')
80	          .eq('restaurant_id', restaurantId);
81	
82	        const counts: Record<number, number> = {};
83	        for (const i of itens ?? []) {
84	          counts[i.product_id] = (counts[i.product_id] ?? 0) + (i.quantity ?? 1);
85	        }
86	        const topIds = Object.entries(counts)
87	          .sort(([, a], [, b]) => b - a)
88	          .slice(0, 12)
89	          .map(([id]) => Number(id));
90	
91	        if (topIds.length > 0) {
92	          const { data } = await this.supabase.client
93	            .from('products').select('id, name, price, preco_promo, image_url, tags, destaque, is_active')
94	            .in('id', topIds).eq('is_active', true).gt('quantidade_estoque', 0);
95	          // Manter ordem por ranking
96	          const prodMap = Object.fromEntries((data ?? []).map((p: any) => [p.id, p]));
97	          produtos = topIds.map((id) => prodMap[id]).filter(Boolean);
98	        }
99	      } else {
100	        // Manual: produtos marcados com esta tag
101	        const { data } = await this.supabase.client
102	          .from('products')
103	          .select('id, name, price, preco_promo, image_url, tags, destaque, is_active, category_id')
104	          .contains('tags', [tag.slug])
105	          .eq('is_active', true)
106	          .gt('quantidade_estoque', 0)
107	          .limit(12);
108	
109	        if (data) {
110	          // Filtrar para este restaurante via category_id
111	          const { data: cats } = await this.supabase.client
112	            .from('categories').select('id')
113	            .or(`restaurant_id.eq.${restaurantId},restaurant_id.is.null`);
114	          const catIds = new Set((cats ?? []).map((c: any) => c.id));
115	          produtos = data.filter((p: any) => catIds.has(p.category_id));
116	        }
117	      }
118	
119	      if (produtos.length > 0) result.push({ tag, produtos });
120	    }
121	
122	    return result;
